// Handles push notifications while the app is closed or in the background.
// This is separate from the main PWA service worker (sw.js, generated by
// vite-plugin-pwa for offline app-shell caching) - Firebase Cloud Messaging
// needs its own service worker file at this exact path/name, and browsers
// happily run both side by side at different scopes.
//
// The config values below are the same ones in src/lib/firebase.ts - they
// are not secret (they're already visible in the deployed app's JS bundle,
// same as every Firebase web app), but this file can't read from .env
// since it's a plain static file, not part of the Vite build - so they're
// written out directly here instead.
importScripts("https://www.gstatic.com/firebasejs/12.18.0/firebase-app-compat.js")
importScripts("https://www.gstatic.com/firebasejs/12.18.0/firebase-messaging-compat.js")

firebase.initializeApp({
  apiKey: "AIzaSyBEiWDuBOFPQk_aF6rVRsuXZGjZTjhm3Qo",
  authDomain: "cleantrack-pool-service.firebaseapp.com",
  projectId: "cleantrack-pool-service",
  storageBucket: "cleantrack-pool-service.firebasestorage.app",
  messagingSenderId: "227876199462",
  appId: "1:227876199462:web:2761583c14ac5e33dd5ae7",
})

const messaging = firebase.messaging()

messaging.onBackgroundMessage((payload) => {
  const title = payload.notification?.title || "TadPool"
  const body = payload.notification?.body || ""
  self.registration.showNotification(title, {
    body,
    icon: "/pwa-192x192.png",
    badge: "/pwa-192x192.png",
    data: payload.data || {},
  })
})

// Tapping the notification focuses an already-open TadPool tab if there is
// one, otherwise opens a new one - and jumps straight to the relevant
// screen (chat thread, job, etc.) via the url the Cloud Function attaches.
self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  const url = event.notification.data?.url || "/"
  event.waitUntil(
    clients.matchAll({ type: "window", includeUncontrolled: true }).then((windowClients) => {
      for (const client of windowClients) {
        if ("focus" in client) {
          client.navigate(url)
          return client.focus()
        }
      }
      if (clients.openWindow) return clients.openWindow(url)
    })
  )
})
